const body = $json.body || {};

const question =
  body.question ||
  body.query ||
  body.message;

if (
  !question ||
  String(question).trim().length === 0
) {
  throw new Error(
    'Question is required. Send JSON body like: ' +
    '{ "question": "..." }'
  );
}

const requestId = String(
  body.request_id ||
  body.requestId ||
  ''
).trim() || null;

return {
  json: {
    question: String(question).trim(),
    request_id: requestId,
    started_at_ms: Date.now()
  }
};

const input = $input.first().json;

const question = String(
  input.question ||
  input.body?.question ||
  ''
).trim();

if (!question) {
  throw new Error('Question is required.');
}

const normalized = question
  .normalize('NFKC')
  .toLocaleLowerCase('tr-TR')
  .replace(/[!?.,:;]/g, '')
  .replace(/\s+/g, ' ')
  .trim();

const greetingWords = [
  'merhaba',
  'selam',
  'selamlar',
  'iyi günler',
  'günaydın',
  'iyi akşamlar',
  'iyi çalışmalar'
];

const assistantInfoPatterns = [
  'sen kimsin',
  'kimsin',
  'nesin',
  'adın ne',
  'kendini tanıt',
  'kendini tanıtır mısın',
  'ne yapabiliyorsun',
  'neler yapabiliyorsun',
  'ne işe yarıyorsun'
];

const thanksPatterns = [
  'teşekkürler',
  'teşekkür ederim',
  'sağ ol',
  'sağol',
  'eyvallah'
];

function includesAny(patterns) {
  return patterns.some((pattern) =>
    normalized.includes(pattern)
  );
}

let staticAnswer = null;

if (greetingWords.includes(normalized)) {
  staticAnswer =
    'Merhaba, ben İZELTAŞ IT Danışma Asistanı’yım. IT destek süreçleriyle ilgili sorularınızda yardımcı olabilirim.';
}

if (
  !staticAnswer &&
  includesAny(assistantInfoPatterns)
) {
  staticAnswer =
    'Ben İZELTAŞ IT Danışma Asistanı’yım. Lokal LLM ve RAG yapısıyla, yüklenen IT destek dokümanlarına göre VPN, şifre, Outlook, yazıcı, donanım, ağ bağlantısı, ortak klasör erişimi, yazılım yetkileri ve ekipman talepleri gibi konularda yardımcı olabilirim.';
}

if (
  !staticAnswer &&
  includesAny(thanksPatterns)
) {
  staticAnswer =
    'Rica ederim. IT süreçleriyle ilgili başka bir konuda da yardımcı olabilirim.';
}

return [
  {
    json: {
      question,
      is_static_response: Boolean(staticAnswer),
      answer: staticAnswer,
      sources: []
    }
  }
];

const items = $input.all();
const intentData = $('Detect Simple Intent').first().json;

const question = String(
  intentData.question || ''
).trim();

// ============================================================
// AYARLAR
// ============================================================

const ENABLE_SCORE_THRESHOLD = true;
const LOWER_SCORE_IS_BETTER = true;

const SCORE_THRESHOLD = 0.51;
const MAX_SOURCES = 3;

// ============================================================
// YARDIMCI FONKSİYONLAR
// ============================================================

function parseMetadata(value) {
  if (!value) {
    return {};
  }

  if (typeof value === 'object') {
    return value;
  }

  try {
    return JSON.parse(value);
  } catch {
    return {};
  }
}

function getContent(row) {
  return String(
    row.pageContent ||
    row.content ||
    row.text ||
    row.document?.pageContent ||
    row.document?.content ||
    row.document?.text ||
    row.json?.pageContent ||
    row.json?.content ||
    row.json?.text ||
    ''
  ).trim();
}

function getMetadata(row) {
  return parseMetadata(
    row.metadata ||
    row.document?.metadata ||
    row.json?.metadata ||
    {}
  );
}

function getScore(row) {
  const value =
    row.score ??
    row.distance ??
    row.json?.score ??
    row.json?.distance ??
    row.document?.score ??
    row.document?.distance ??
    null;

  if (value === null || value === undefined) {
    return null;
  }

  const numberValue = Number(value);

  if (Number.isNaN(numberValue)) {
    return null;
  }

  return numberValue;
}

function isScoreAccepted(score) {
  if (!ENABLE_SCORE_THRESHOLD) {
    return true;
  }

  if (score === null) {
    return false;
  }

  if (LOWER_SCORE_IS_BETTER) {
    return score <= SCORE_THRESHOLD;
  }

  return score >= SCORE_THRESHOLD;
}

function compareScores(firstDocument, secondDocument) {
  const firstScore = firstDocument.score;
  const secondScore = secondDocument.score;

  if (firstScore === null && secondScore === null) {
    return 0;
  }

  if (firstScore === null) {
    return 1;
  }

  if (secondScore === null) {
    return -1;
  }

  if (LOWER_SCORE_IS_BETTER) {
    return firstScore - secondScore;
  }

  return secondScore - firstScore;
}

// ============================================================
// N8N ÇIKTILARINI TEK LİSTEYE DÖNÜŞTÜR
// ============================================================

const documents = [];

for (const item of items) {
  const row = item.json || {};

  if (Array.isArray(row.documents)) {
    for (const document of row.documents) {
      documents.push(document);
    }

    continue;
  }

  if (Array.isArray(row.results)) {
    for (const document of row.results) {
      documents.push(document);
    }

    continue;
  }

  documents.push(row);
}

// ============================================================
// ADAY DOKÜMANLARI HAZIRLA
// ============================================================

const candidateDocuments = documents
  .map((document, index) => {
    return {
      content: getContent(document),
      metadata: getMetadata(document),
      score: getScore(document),
      original_index: index
    };
  })
  .filter((document) => document.content.length > 20)
  .sort(compareScores);

const usefulDocuments = candidateDocuments
  .filter((document) =>
    isScoreAccepted(document.score)
  )
  .slice(0, MAX_SOURCES);

// ============================================================
// LLM CONTEXT HAZIRLA
// ============================================================

const context = usefulDocuments.length > 0
  ? usefulDocuments
      .map((document, index) => {
        const metadata = document.metadata || {};
        const sectionTitle =
          metadata.section_title || '';

        return [
          `[PASSAGE ${index + 1}]`,
          sectionTitle
            ? `TOPIC: ${sectionTitle}`
            : '',
          document.content
        ]
          .filter(Boolean)
          .join('\n');
      })
      .join('\n\n---\n\n')
  : 'NO_RELEVANT_SOURCE';

// ============================================================
// FRONTEND'E DÖNECEK KAYNAKLAR
// ============================================================

const sources = usefulDocuments.map(
  (document, index) => {
    const metadata = document.metadata || {};

    return {
      document_id:
        metadata.document_id || null,

      title:
        metadata.title || null,

      category:
        metadata.category || null,

      section_title:
        metadata.section_title || null,

      chunk_index:
        metadata.chunk_index ?? index + 1,

      source_file_name:
        metadata.source_file_name || null,

      file_type:
        metadata.file_type || null,

      score:
        document.score
    };
  }
);

// ============================================================
// PROMPT
// ============================================================

const prompt = `
You are an internal IT support assistant for İZELTAŞ.

The PASSAGES below are candidate sections returned by the retrieval system.

Answer the USER QUESTION using only the information explicitly stated in the PASSAGES.
Select only the passages and statements that directly answer the question.
Ignore unrelated passages and unrelated details.
Do not return NO_RELEVANT_SOURCE.

SECURITY RULES:

- Never tell the user to share, send or include passwords, MFA codes, access tokens, API keys or other secret credentials in a support request, form, e-mail or message.
- Password reset, password change and official login instructions are allowed.
- Do not add a security warning merely because a passage mentions a password.
- If a passage explicitly asks the user to share a secret credential, omit only that unsafe instruction and write:
  "Parola, MFA doğrulama kodu veya başka bir gizli bilgi paylaşılmamalıdır."

SOURCE RULES:

- Use only information explicitly stated in the PASSAGES.
- Do not invent, infer or complete missing information.
- Select concrete instructions, requirements and conditions that answer the USER QUESTION.
- Do not answer only with a sentence that describes what a document covers when concrete instructions are available.
- Preserve the original meaning, conditions, warnings and negations.
- Never reverse or remove expressions such as "değil", "olmadığından", "olmamalıdır" or "yapılmamalıdır".
- Never omit conditions such as "açılmıyorsa", "devam ederse", "tamamlandıktan sonra" or "varsa".
- Prefer complete source sentences and keep their wording close to the original.
- Do not unnecessarily change Turkish case suffixes, possessive suffixes, subjects or verb conjugations.
- Do not merge sentences when merging them could cause a grammatical or semantic error.

LANGUAGE AND FORMAT:

- Write in Turkish only.
- Return between 1 and 3 bullet points.
- Start every bullet point with "- ".
- Each bullet point must contain one relevant and complete instruction or requirement.
- Combine complementary information from different passages when it directly helps answer the question.
- Do not include unrelated information merely to produce 3 bullet points.
- Do not repeat the USER QUESTION.
- Do not write a title, introduction or conclusion.
- Do not ask a follow-up question.
- Do not mention passages, sources, documents, metadata, chunks, scores or the retrieval process.
- Before returning the answer, check that every sentence is complete, natural and grammatically correct Turkish.

PASSAGES:

${context}

USER QUESTION:

${question}

Return only the Turkish bullet points.
`;

// ============================================================
// DEBUG BİLGİLERİ
// ============================================================

const debug = {
  threshold_enabled:
    ENABLE_SCORE_THRESHOLD,

  threshold:
    SCORE_THRESHOLD,

  lower_score_is_better:
    LOWER_SCORE_IS_BETTER,

  max_sources:
    MAX_SOURCES,

  candidate_count:
    candidateDocuments.length,

  threshold_pass_count:
  candidateDocuments.filter((document) =>
    isScoreAccepted(document.score)
  ).length,

  selected_count:
    usefulDocuments.length,

  candidate_documents:
    candidateDocuments.map((document) => {
      return {
        document_id:
          document.metadata?.document_id || null,

        title:
          document.metadata?.title || null,

        section_title:
          document.metadata?.section_title || null,

        score:
          document.score,

        accepted:
          isScoreAccepted(document.score)
      };
    })
};

// ============================================================
// N8N ÇIKIŞI
// ============================================================

return [
  {
    json: {
      question,
      context,
      prompt,
      sources,
      debug
    }
  }
];

const buildPromptOutput = $('Build Prompt').first().json;

const question = String(
  buildPromptOutput.question || ''
).trim();

const sources = Array.isArray(buildPromptOutput.sources)
  ? buildPromptOutput.sources
  : [];

const context = String(
  buildPromptOutput.context || ''
).trim();

const noRelevantSourceAnswer =
  '- Bu konuda kaynak dokümanlarda yeterli bilgi bulamadım. IT destek ekibiyle iletişime geçebilirsiniz.';

const llmErrorAnswer =
  '- Şu anda yapay zeka modeli geçerli bir yanıt üretemedi. Lütfen daha sonra tekrar deneyin veya IT destek ekibiyle iletişime geçin.';

const unsafeCredentialWarning =
  'Parola, MFA doğrulama kodu, erişim anahtarı veya başka bir gizli bilgi paylaşılmamalıdır.';

// ============================================================
// 1. KAYNAK BULUNAMADI
// ============================================================

if (
  sources.length === 0 ||
  context === 'NO_RELEVANT_SOURCE'
) {
  return {
    json: {
      question,
      answer: noRelevantSourceAnswer,
      sources: [],
      response_type: 'no_relevant_source'
    }
  };
}

// ============================================================
// 2. LLM NODE HATASI
// ============================================================

const hasNodeError =
  Boolean($json.error) ||
  Boolean($json.stack) ||
  Boolean(
    $json.message &&
    String($json.message)
      .toLocaleLowerCase('tr-TR')
      .includes('error')
  );

if (hasNodeError) {
  return {
    json: {
      question,
      answer: llmErrorAnswer,
      sources,
      response_type: 'llm_error'
    }
  };
}

// ============================================================
// 3. LLM CEVABINI AL
// ============================================================

const rawAnswer = String(
  $json.text ??
  $json.output ??
  $json.response ??
  $json.answer ??
  $json.result ??
  $json.data?.text ??
  $json.data?.output ??
  ''
).trim();

if (!rawAnswer) {
  return {
    json: {
      question,
      answer: llmErrorAnswer,
      sources,
      response_type: 'llm_error'
    }
  };
}

// ============================================================
// 4. GENEL METİN TEMİZLİĞİ
// ============================================================

function cleanOutput(text) {
  return String(text || '')
    .replace(/```(?:text|plaintext)?/gi, '')
    .replace(/```/g, '')
    .replace(/^["'`]+|["'`]+$/g, '')
    .replace(/\r\n/g, '\n')
    .replace(/[ \t]+/g, ' ')
    .replace(/\s+([.!?,;:])/g, '$1')
    .replace(/([.!?]){2,}/g, '$1')
    .trim();
}

const cleanedRawAnswer = cleanOutput(rawAnswer);

// Kaynak bulunduğu hâlde model sentinel döndürürse
// retrieval hatası değil, LLM üretim hatasıdır.
if (
  /^NO_RELEVANT_SOURCE[.!]?$/i.test(
    cleanedRawAnswer
  )
) {
  return {
    json: {
      question,
      answer:
        '- Kaynak bulundu ancak yapay zeka modeli geçerli bir yanıt üretemedi. Lütfen tekrar deneyin.',
      sources,
      response_type: 'llm_error'
    }
  };
}

// ============================================================
// 5. GEÇERSİZ AÇIKLAMA SATIRLARI
// ============================================================

function isInvalidLine(text) {
  const normalized = String(text || '')
    .toLocaleLowerCase('tr-TR')
    .trim();

  const invalidPatterns = [
    'source text',
    'kaynak metin',
    'metadata',
    'chunk',
    'document_id',
    'section title',
    'bölüm başlığı',
    'final answer',
    'final cevap',
    'cevap veriyorum'
  ];

  return invalidPatterns.some((pattern) =>
    normalized.includes(pattern)
  );
}

// ============================================================
// 6. AÇIK GİZLİ BİLGİ İHLALLERİNİ ENGELLE
// ============================================================

function sanitizeUnsafeCredentialInstruction(text) {
  const original = String(text || '').trim();

  const normalized = original
    .toLocaleLowerCase('tr-TR')
    .replace(/\s+/g, ' ')
    .trim();

  const containsSecret =
    /(parola|şifre|mfa doğrulama kodu|mfa kodu|erişim anahtarı|api anahtarı|access token|erişim belirteci)/i
      .test(normalized);

  if (!containsSecret) {
    return original;
  }

  // Zaten güvenli bir yasaklama veya uyarıysa değiştirme.
  const isSafeWarning =
    /(paylaşmayın|paylaşılmamalı|göndermeyin|gönderilmemeli|iletmeyin|iletilmemeli|eklemeyin|eklenmemeli|ifşa etmeyin|ifşa edilmemeli|verilmemeli|verilmez)/i
      .test(normalized);

  if (isSafeWarning) {
    return original;
  }

  // Doğrudan gizli bilgi paylaşılmasını isteyen ifadeler.
  const hasDirectDisclosureAction =
    /(paylaşın|paylaşınız|paylaşılmalıdır|gönderin|gönderiniz|gönderilmelidir|iletin|iletiniz|iletilmelidir|ifşa edin|ifşa edilmelidir)/i
      .test(normalized);

  // Talep, form, e-posta veya mesaja gizli bilgi
  // eklenmesini isteyen ifadeler.
  const hasInclusionAction =
    /(ekleyin|ekleyiniz|eklenmelidir|yazın|yazınız|yazılmalıdır|belirtin|belirtiniz|belirtilmelidir)/i
      .test(normalized);

  const hasSupportDestination =
    /(destek talebi|destek kaydı|talep formu|başvuru formu|e-posta|e posta|mail|mesaj|ticket)/i
      .test(normalized);

  if (
    hasDirectDisclosureAction ||
    (
      hasInclusionAction &&
      hasSupportDestination
    )
  ) {
    return unsafeCredentialWarning;
  }

  // Şifre sıfırlama, değiştirme veya giriş işlemleri korunur.
  return original;
}

// ============================================================
// 7. TEKRAR KONTROLÜ İÇİN NORMALİZE ET
// ============================================================

function createComparisonKey(text) {
  return String(text || '')
    .toLocaleLowerCase('tr-TR')
    .replace(/[.!?,;:]+/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

// ============================================================
// 8. CEVABI MADDE FORMATINA DÖNÜŞTÜR
// ============================================================

function normalizeBullets(answer) {
  const cleaned = cleanOutput(answer);

  if (!cleaned) {
    return null;
  }

  const lines = cleaned
    .split('\n')
    .map((line) => line.trim())
    .filter(Boolean);

  // Model madde işareti kullandıysa yalnızca maddeleri al.
  let bulletLines = lines.filter((line) =>
    /^[-•*]\s+/.test(line)
  );

  // Madde işareti yoksa cümleleri ayrı maddelere dönüştür.
  if (bulletLines.length === 0) {
    bulletLines = cleaned
      .split(/(?<=[.!?])\s+/)
      .map((sentence) => sentence.trim())
      .filter(Boolean);
  } else {
    bulletLines = bulletLines.map((line) =>
      line.replace(/^[-•*]\s+/, '').trim()
    );
  }

  bulletLines = bulletLines
    .map(cleanOutput)
    .map(sanitizeUnsafeCredentialInstruction)
    .filter(Boolean)
    .filter((line) => !isInvalidLine(line));

  // Aynı maddeleri tekrar etme.
  const seen = new Set();

  bulletLines = bulletLines.filter((line) => {
    const key = createComparisonKey(line);

    if (!key || seen.has(key)) {
      return false;
    }

    seen.add(key);
    return true;
  });

  if (bulletLines.length === 0) {
    return null;
  }

  return bulletLines
    .slice(0, 3)
    .map((line) => {
      let text = cleanOutput(line);

      if (!/[.!?]$/.test(text)) {
        text += '.';
      }

      return `- ${text}`;
    })
    .join('\n');
}

// ============================================================
// 9. SONUCU DÖNDÜR
// ============================================================

const normalizedAnswer =
  normalizeBullets(cleanedRawAnswer);

if (!normalizedAnswer) {
  return {
    json: {
      question,
      answer: llmErrorAnswer,
      sources,
      response_type: 'llm_error'
    }
  };
}

return {
  json: {
    question,
    answer: normalizedAnswer,
    sources,
    response_type: 'rag_answer'
  }
};

const chatData = $('Prepare Chat Log Data').first().json;

return {
  json: {
    question: chatData.question,
    answer: chatData.answer,
    sources: chatData.sources || [],
    response_type: chatData.response_type || "unknown"
  }
};

const question = $json.question;

return {
  json: {
    question,
    answer:
      '- Bu konuda kaynak dokümanlarda yeterli bilgi bulamadım. IT destek ekibiyle iletişime geçebilirsiniz.',
    sources: [],
    response_type: 'no_relevant_source'
  }
};

const question = String(
  $json.question || ''
).trim();

const answer = String(
  $json.answer || ''
).trim();

const sources = Array.isArray($json.sources)
  ? $json.sources
  : [];


if (!question) {
  throw new Error(
    'Question is required for chat log.'
  );
}

if (!answer) {
  throw new Error(
    'Answer is required for chat log.'
  );
}

const requestData =
  $('Get User Question').first().json;

const requestId = String(
  requestData.request_id || ''
).trim() || null;

const startedAtMs = Number(
  requestData.started_at_ms
);

let durationMs = null;

if (Number.isFinite(startedAtMs)) {
  durationMs = Math.max(
    0,
    Date.now() - startedAtMs
  );
}


const sourceCount = sources.length;



function maskSensitiveText(value) {
  return String(value ?? '')
    .replace(
      /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi,
      '[masked_email]'
    )
    .replace(
      /(\+90|0)?\s?5\d{2}\s?\d{3}\s?\d{2}\s?\d{2}/g,
      '[masked_phone]'
    )
    .replace(
      /\b\d{8,}\b/g,
      '[masked_number]'
    );
}


const firstSource = sources[0] || {};

const category =
  firstSource.category || null;

const sectionTitle =
  firstSource.section_title || null;

const responseType =
  $json.response_type ||
  (
    sources.length > 0
      ? 'rag_answer'
      : 'unknown'
  );



const maskedQuestion =
  maskSensitiveText(question);

const maskedAnswer =
  maskSensitiveText(answer);


return {
  json: {
    request_id: requestId,
    duration_ms: durationMs,
    source_count: sourceCount,

    question,
    answer,
    sources,

    question_masked: maskedQuestion,
    answer_masked: maskedAnswer,

    sources_json: {
      source_items: sources
    },

    category,
    section_title: sectionTitle,
    response_type: responseType
  }
};

const question = String(
  $json.question || ''
).trim();

return {
  json: {
    question,
    answer:
      '- Bu asistan yalnızca IT destek konularında yardımcı olabilir.',
    sources: [],
    response_type: 'out_of_scope'
  }
};

const buildPromptData =
  $('Build Prompt').first().json;

const question = String(
  buildPromptData.question || ''
).trim();

const rawClassification = String(
  $json.text ??
  $json.output ??
  $json.response ??
  $json.answer ??
  $json.result ??
  ''
).trim();

const hasClassifierError =
  Boolean($json.error) ||
  Boolean($json.stack);

const cleanedClassification =
  rawClassification
    .replace(/```(?:text|plaintext)?/gi, '')
    .replace(/```/g, '')
    .replace(/^["'`]+|["'`]+$/g, '')
    .trim()
    .toUpperCase();

let scopeClassification;

if (
  !hasClassifierError &&
  /^OUT_OF_SCOPE[.!]?$/.test(
    cleanedClassification
  )
) {
  scopeClassification = 'OUT_OF_SCOPE';
} else if (
  !hasClassifierError &&
  /^IT_RELATED[.!]?$/.test(
    cleanedClassification
  )
) {
  scopeClassification = 'IT_RELATED';
} else {
  /*
   * Güvenli varsayılan:
   *
   * Sınıflandırıcı hata verir veya beklenmeyen
   * bir çıktı üretirse gerçek bir IT sorusunu
   * yanlışlıkla reddetmemek için IT_RELATED kabul edilir.
   */
  scopeClassification = 'IT_RELATED';
}

return {
  json: {
    question,
    scope_classification:
      scopeClassification,

    raw_scope_classification:
      rawClassification,

    classifier_fallback_used:
      hasClassifierError ||
      !/^(IT_RELATED|OUT_OF_SCOPE)[.!]?$/.test(
        cleanedClassification
      )
  }
};
